<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: #f0f2f5;
    color: #1c1e21;
    min-height: 100vh;
    padding: 32px 24px;
  }
  h1 {
    font-size: 24px;
    font-weight: 700;
    margin-bottom: 24px;
    text-align: center;
    color: #1a1a2e;
  }
  .toolbar {
    display: flex;
    gap: 8px;
    justify-content: center;
    margin-bottom: 32px;
  }
  #new-card {
    width: 320px;
    max-width: 60vw;
    padding: 10px 14px;
    border: 1px solid #ccd0d5;
    border-radius: 8px;
    font-size: 15px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card:focus {
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67,97,238,.15);
  }
  #add-card {
    padding: 10px 20px;
    border: none;
    border-radius: 8px;
    background: #4361ee;
    color: #fff;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
  }
  #add-card:hover { background: #3a53c9; }
  #add-card:active { transform: translateY(1px); }
  .board {
    display: flex;
    gap: 20px;
    justify-content: center;
    align-items: flex-start;
    flex-wrap: wrap;
    max-width: 1100px;
    margin: 0 auto;
  }
  .column {
    background: #ebecf0;
    border-radius: 12px;
    width: 320px;
    max-width: 90vw;
    display: flex;
    flex-direction: column;
    padding: 12px;
    transition: background .15s, box-shadow .15s;
  }
  .column.drag-over {
    background: #dde3f5;
    box-shadow: inset 0 0 0 2px #4361ee;
  }
  .column-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 4px 8px 12px;
    font-size: 15px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .04em;
    color: #5a5f6a;
  }
  .count {
    background: #d0d3d9;
    color: #4a4f5a;
    font-size: 13px;
    font-weight: 700;
    min-width: 24px;
    height: 24px;
    padding: 0 8px;
    border-radius: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .cards {
    min-height: 60px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
  }
  .card {
    background: #fff;
    border-radius: 8px;
    padding: 12px 14px;
    box-shadow: 0 1px 2px rgba(0,0,0,.08), 0 1px 1px rgba(0,0,0,.04);
    cursor: grab;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    font-size: 15px;
    line-height: 1.4;
    word-break: break-word;
    transition: box-shadow .15s, transform .1s;
  }
  .card:hover { box-shadow: 0 3px 8px rgba(0,0,0,.12); }
  .card.dragging {
    opacity: .5;
    cursor: grabbing;
  }
  .card-title { flex: 1; }
  .card-del {
    border: none;
    background: transparent;
    color: #9aa0a8;
    font-size: 18px;
    line-height: 1;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 4px;
    flex-shrink: 0;
    transition: background .15s, color .15s;
  }
  .card-del:hover { background: #ffe5e5; color: #e03131; }
</style>
</head>
<body>
  <h1>Kanban Board</h1>
  <div class="toolbar">
    <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off">
    <button id="add-card">Add Card</button>
  </div>
  <div class="board">
    <div class="column" id="col-todo" data-col="todo">
      <div class="column-header"><span>To Do</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
    <div class="column" id="col-doing" data-col="doing">
      <div class="column-header"><span>Doing</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
    <div class="column" id="col-done" data-col="done">
      <div class="column-header"><span>Done</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
  </div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban.board.v1";
  var COLUMNS = ["todo", "doing", "done"];

  // state: array of { id, title, col }
  var cards = load();
  var nextId = cards.reduce(function (m, c) { return Math.max(m, c.id); }, 0) + 1;

  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data.filter(function (c) {
        return c && typeof c.title === "string" && COLUMNS.indexOf(c.col) !== -1;
      }).map(function (c, i) {
        return { id: typeof c.id === "number" ? c.id : i + 1, title: c.title, col: c.col };
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
    } catch (e) { /* ignore */ }
  }

  function cardsContainer(col) {
    return document.querySelector("#col-" + col + " .cards");
  }

  function countEl(col) {
    return document.querySelector("#col-" + col + " .count");
  }

  function buildCardEl(card) {
    var el = document.createElement("div");
    el.className = "card";
    el.setAttribute("draggable", "true");
    el.dataset.id = String(card.id);

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "\u00D7";
    del.addEventListener("click", function (e) {
      e.stopPropagation();
      deleteCard(card.id);
    });

    el.appendChild(title);
    el.appendChild(del);

    el.addEventListener("dragstart", function (e) {
      el.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", String(card.id));
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
    });

    return el;
  }

  function render() {
    COLUMNS.forEach(function (col) {
      cardsContainer(col).innerHTML = "";
    });
    cards.forEach(function (card) {
      cardsContainer(card.col).appendChild(buildCardEl(card));
    });
    updateCounts();
  }

  function updateCounts() {
    COLUMNS.forEach(function (col) {
      var n = cards.filter(function (c) { return c.col === col; }).length;
      countEl(col).textContent = String(n);
    });
  }

  function addCard() {
    var text = input.value.trim();
    if (!text) return;
    cards.push({ id: nextId++, title: text, col: "todo" });
    input.value = "";
    save();
    render();
    input.focus();
  }

  function deleteCard(id) {
    cards = cards.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col) {
    var card = cards.find(function (c) { return c.id === id; });
    if (!card || card.col === col || COLUMNS.indexOf(col) === -1) return;
    card.col = col;
    save();
    render();
  }

  // Wire up controls
  addBtn.addEventListener("click", addCard);
  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter") { e.preventDefault(); addCard(); }
  });

  // Drag-and-drop on columns
  COLUMNS.forEach(function (col) {
    var column = document.getElementById("col-" + col);

    column.addEventListener("dragover", function (e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      column.classList.add("drag-over");
    });
    column.addEventListener("dragleave", function (e) {
      // Only clear when leaving the column entirely
      if (!column.contains(e.relatedTarget)) {
        column.classList.remove("drag-over");
      }
    });
    column.addEventListener("drop", function (e) {
      e.preventDefault();
      column.classList.remove("drag-over");
      var raw = e.dataTransfer.getData("text/plain");
      var id = parseInt(raw, 10);
      if (!isNaN(id)) moveCard(id, col);
    });
  });

  render();
})();
</script>
</body>
</html>
